/* A store's currency change converts what it should and nothing else (part 176 again, three functions replaced). Membership and community plans are priced and billed in US dollars whatever the store sells in (lib/money/product-currency), so a change no longer converts those products' prices: a $10 plan stayed $10 at Stripe while its card read $49.70 after a change to lei. Offers' fixed amounts off and their minimum basket (store_offers.discount_value when fixed, min_subtotal_cents) and a smart collection's price and compare-at price conditions (product_collections.rules) are in the store's currency and are now converted with everything else, kept in the change's snapshots and put back by Undo, so a €5 off bundle does not become 5 lei off and a "price under 30" collection still holds the same products. Orders, refunds and payouts are still never touched. Needs part 176. Safe to run again. */
CREATE OR REPLACE FUNCTION public.store_currency_targets() RETURNS TABLE (table_name text, key_column text, store_filter text, money_columns text[]) LANGUAGE sql IMMUTABLE AS $fn$ VALUES ('products', 'id', 'creator_id = $1 AND coalesce(type, '''') NOT IN (''membership'', ''community'')', ARRAY['price_cents', 'compare_at_cents', 'pwyw_min_price_cents', 'pwyw_suggested_price_cents']), ('product_variants', 'id', 'product_id IN (SELECT p.id FROM public.products p WHERE p.creator_id = $1 AND coalesce(p.type, '''') NOT IN (''membership'', ''community''))', ARRAY['price_cents', 'compare_at_price_cents', 'additional_price_cents']), ('product_variant_costs', 'variant_id', 'creator_id = $1', ARRAY['cost_cents']), ('shipping_rates', 'id', 'creator_id = $1', ARRAY['price_cents', 'free_over_cents']), ('inventory_locations', 'id', 'creator_id = $1', ARRAY['local_delivery_price_cents', 'local_delivery_min_cents', 'local_delivery_free_over_cents']), ('coupons', 'id', 'creator_id = $1', ARRAY['min_purchase_cents']), ('store_offers', 'id', 'creator_id = $1', ARRAY['min_subtotal_cents']), ('product_collections', 'id', 'creator_id = $1 AND kind = ''smart'' AND EXISTS (SELECT 1 FROM jsonb_array_elements(rules) r WHERE r->>''field'' IN (''price'', ''compare_at_price''))', ARRAY[]::text[]) $fn$;
CREATE OR REPLACE FUNCTION public.store_change_currency(p_creator uuid, p_from text, p_to text, p_mode text, p_rate numeric, p_rate_as_of date, p_key text, p_user uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path = public AS $fn$ DECLARE v_prev public.store_currency_changes%ROWTYPE; v_stored text; v_change uuid := gen_random_uuid(); v_counts jsonb := '{}'::jsonb; v_target record; v_cols text[]; v_set text; v_snap text; v_n integer; BEGIN IF p_creator IS NULL THEN RAISE EXCEPTION 'store_currency: no store' USING ERRCODE = '22023'; END IF; IF p_from IS NULL OR p_to IS NULL OR p_from !~ '^[A-Z]{3}$' OR p_to !~ '^[A-Z]{3}$' THEN RAISE EXCEPTION 'store_currency: a currency is not a code' USING ERRCODE = '22023'; END IF; IF p_from = p_to THEN RAISE EXCEPTION 'store_currency: the store already sells in %', p_to USING ERRCODE = '22023'; END IF; IF p_mode IS NULL OR p_mode NOT IN ('keep', 'convert') THEN RAISE EXCEPTION 'store_currency: mode is keep or convert' USING ERRCODE = '22023'; END IF; IF p_mode = 'convert' AND (p_rate IS NULL OR p_rate <= 0 OR p_rate > 1000000) THEN RAISE EXCEPTION 'store_currency: converting needs a rate' USING ERRCODE = '22023'; END IF; IF p_key IS NULL OR length(p_key) NOT BETWEEN 8 AND 120 THEN RAISE EXCEPTION 'store_currency: a request key is needed' USING ERRCODE = '22023'; END IF; INSERT INTO public.store_settings (creator_id) VALUES (p_creator) ON CONFLICT (creator_id) DO NOTHING; SELECT currency INTO v_stored FROM public.store_settings WHERE creator_id = p_creator FOR UPDATE; SELECT * INTO v_prev FROM public.store_currency_changes WHERE creator_id = p_creator AND request_key = p_key; IF FOUND THEN RETURN jsonb_build_object('ok', true, 'repeat', true, 'id', v_prev.id, 'from', v_prev.from_currency, 'to', v_prev.to_currency, 'mode', v_prev.mode, 'rate', v_prev.rate, 'counts', v_prev.counts); END IF; IF coalesce(v_stored, p_from) <> p_from THEN RAISE EXCEPTION 'store_currency: the store now sells in %', v_stored USING ERRCODE = '40001'; END IF; INSERT INTO public.store_currency_changes (id, creator_id, from_currency, to_currency, previous_currency, mode, rate, rate_as_of, request_key, created_by) VALUES (v_change, p_creator, p_from, p_to, v_stored, p_mode, CASE WHEN p_mode = 'convert' THEN p_rate END, CASE WHEN p_mode = 'convert' THEN p_rate_as_of END, p_key, p_user); IF p_mode = 'convert' THEN FOR v_target IN SELECT * FROM public.store_currency_targets() LOOP IF to_regclass('public.' || v_target.table_name) IS NULL THEN CONTINUE; END IF; SELECT array_agg(c ORDER BY c) INTO v_cols FROM unnest(v_target.money_columns) AS c WHERE EXISTS (SELECT 1 FROM information_schema.columns ic WHERE ic.table_schema = 'public' AND ic.table_name = v_target.table_name AND ic.column_name = c); IF v_target.table_name = 'shipping_rates' THEN v_cols := coalesce(v_cols, ARRAY[]::text[]) || ARRAY['min_value', 'max_value', 'tiers', 'kind']; ELSIF v_target.table_name = 'coupons' THEN v_cols := coalesce(v_cols, ARRAY[]::text[]) || ARRAY['discount_value', 'discount_type']; ELSIF v_target.table_name = 'store_offers' THEN v_cols := coalesce(v_cols, ARRAY[]::text[]) || ARRAY['discount_value', 'discount_type']; ELSIF v_target.table_name = 'product_collections' THEN v_cols := ARRAY['rules']; END IF; IF v_cols IS NULL OR array_length(v_cols, 1) IS NULL THEN CONTINUE; END IF; v_snap := format('INSERT INTO public.store_currency_snapshots (change_id, table_name, row_id, before) SELECT $2, %L, t.%I, jsonb_build_object(%s) FROM public.%I t WHERE %s', v_target.table_name, v_target.key_column, (SELECT string_agg(format('%L, t.%I', c, c), ', ') FROM unnest(v_cols) AS c), v_target.table_name, v_target.store_filter); EXECUTE v_snap USING p_creator, v_change; GET DIAGNOSTICS v_n = ROW_COUNT; IF v_target.table_name = 'shipping_rates' THEN v_set := concat_ws(', ', CASE WHEN 'price_cents' = ANY (v_cols) THEN 'price_cents = round(price_cents * $2)::integer' END, CASE WHEN 'free_over_cents' = ANY (v_cols) THEN 'free_over_cents = CASE WHEN free_over_cents IS NULL THEN NULL ELSE round(free_over_cents * $2)::integer END' END, 'min_value = CASE WHEN kind = ''price'' AND min_value IS NOT NULL THEN round(min_value * $2)::integer ELSE min_value END', 'max_value = CASE WHEN kind = ''price'' AND max_value IS NOT NULL THEN round(max_value * $2)::integer ELSE max_value END', 'tiers = CASE WHEN jsonb_typeof(tiers) = ''array'' AND jsonb_array_length(tiers) > 0 THEN (SELECT coalesce(jsonb_agg(CASE WHEN jsonb_typeof(x) = ''object'' THEN x || jsonb_strip_nulls(jsonb_build_object(''priceCents'', CASE WHEN x ? ''priceCents'' THEN round((x->>''priceCents'')::numeric * $2)::integer END, ''from'', CASE WHEN kind = ''price'' AND x ? ''from'' THEN round((x->>''from'')::numeric * $2)::integer END)) ELSE x END ORDER BY o), ''[]''::jsonb) FROM jsonb_array_elements(tiers) WITH ORDINALITY AS e(x, o)) ELSE tiers END'); ELSIF v_target.table_name = 'coupons' THEN v_set := concat_ws(', ', CASE WHEN 'min_purchase_cents' = ANY (v_cols) THEN 'min_purchase_cents = CASE WHEN min_purchase_cents IS NULL THEN NULL ELSE round(min_purchase_cents * $2)::integer END' END, 'discount_value = CASE WHEN discount_type = ''fixed'' THEN greatest(0.01, round(discount_value * $2, 2)) ELSE discount_value END'); ELSIF v_target.table_name = 'store_offers' THEN v_set := concat_ws(', ', CASE WHEN 'min_subtotal_cents' = ANY (v_cols) THEN 'min_subtotal_cents = CASE WHEN min_subtotal_cents IS NULL THEN NULL ELSE round(min_subtotal_cents * $2)::integer END' END, 'discount_value = CASE WHEN discount_type = ''fixed'' THEN greatest(1, round(discount_value * $2))::integer ELSE discount_value END'); ELSIF v_target.table_name = 'product_collections' THEN v_set := 'rules = (SELECT coalesce(jsonb_agg(CASE WHEN jsonb_typeof(x) = ''object'' AND x->>''field'' IN (''price'', ''compare_at_price'') AND (x->>''value'') ~ ''^\s*[0-9]+(\.[0-9]+)?\s*$'' THEN jsonb_set(x, ''{value}'', to_jsonb(regexp_replace(regexp_replace(round(btrim(x->>''value'')::numeric * $2, 2)::text, ''0+$'', ''''), ''\.$'', ''''))) ELSE x END ORDER BY o), ''[]''::jsonb) FROM jsonb_array_elements(rules) WITH ORDINALITY AS e(x, o))'; ELSE SELECT string_agg(format('%1$I = CASE WHEN %1$I IS NULL THEN NULL ELSE round(%1$I * $2)::integer END', c), ', ') INTO v_set FROM unnest(v_cols) AS c; END IF; EXECUTE format('UPDATE public.%I SET %s WHERE %s', v_target.table_name, v_set, v_target.store_filter) USING p_creator, p_rate; v_counts := v_counts || jsonb_build_object(v_target.table_name, v_n); END LOOP; INSERT INTO public.store_currency_snapshots (change_id, table_name, row_id, before) SELECT v_change, 'store_settings', s.creator_id, jsonb_build_object('codFeeCents', s.checkout->'codFeeCents') FROM public.store_settings s WHERE s.creator_id = p_creator AND jsonb_typeof(s.checkout->'codFeeCents') = 'number'; GET DIAGNOSTICS v_n = ROW_COUNT; IF v_n > 0 THEN UPDATE public.store_settings SET checkout = jsonb_set(checkout, '{codFeeCents}', to_jsonb(round((checkout->>'codFeeCents')::numeric * p_rate)::integer)) WHERE creator_id = p_creator; v_counts := v_counts || jsonb_build_object('cod_fee', 1); END IF; END IF; UPDATE public.store_settings SET currency = p_to, updated_at = now() WHERE creator_id = p_creator; UPDATE public.store_currency_changes SET counts = v_counts WHERE id = v_change; RETURN jsonb_build_object('ok', true, 'repeat', false, 'id', v_change, 'from', p_from, 'to', p_to, 'mode', p_mode, 'rate', CASE WHEN p_mode = 'convert' THEN p_rate END, 'counts', v_counts); END $fn$;
CREATE OR REPLACE FUNCTION public.store_currency_restore(p_creator uuid, p_change uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path = public AS $fn$ DECLARE v_change public.store_currency_changes%ROWTYPE; v_latest uuid; v_target record; v_cols text[]; v_set text; v_counts jsonb := '{}'::jsonb; v_n integer; BEGIN PERFORM 1 FROM public.store_settings WHERE creator_id = p_creator FOR UPDATE; SELECT * INTO v_change FROM public.store_currency_changes WHERE id = p_change AND creator_id = p_creator; IF NOT FOUND THEN RAISE EXCEPTION 'store_currency: no such change' USING ERRCODE = '22023'; END IF; IF v_change.restored_at IS NOT NULL THEN RETURN jsonb_build_object('ok', true, 'repeat', true, 'currency', v_change.from_currency); END IF; SELECT id INTO v_latest FROM public.store_currency_changes WHERE creator_id = p_creator AND restored_at IS NULL ORDER BY created_at DESC, id DESC LIMIT 1; IF v_latest IS DISTINCT FROM p_change THEN RAISE EXCEPTION 'store_currency: only the latest change can be undone' USING ERRCODE = '40001'; END IF; FOR v_target IN SELECT * FROM public.store_currency_targets() LOOP IF to_regclass('public.' || v_target.table_name) IS NULL THEN CONTINUE; END IF; SELECT array_agg(DISTINCT k) INTO v_cols FROM public.store_currency_snapshots s, jsonb_object_keys(s.before) AS k WHERE s.change_id = p_change AND s.table_name = v_target.table_name AND k NOT IN ('kind', 'discount_type'); IF v_cols IS NULL THEN CONTINUE; END IF; SELECT string_agg( CASE c WHEN 'tiers' THEN 'tiers = s.before->''tiers''' WHEN 'rules' THEN 'rules = s.before->''rules''' WHEN 'discount_value' THEN 'discount_value = (s.before->>''discount_value'')::numeric' ELSE format('%1$I = (s.before->>%1$L)::integer', c) END, ', ') INTO v_set FROM unnest(v_cols) AS c; EXECUTE format('UPDATE public.%I t SET %s FROM public.store_currency_snapshots s WHERE s.change_id = $1 AND s.table_name = %L AND t.%I = s.row_id', v_target.table_name, v_set, v_target.table_name, v_target.key_column) USING p_change; GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object(v_target.table_name, v_n); END LOOP; UPDATE public.store_settings t SET checkout = jsonb_set(t.checkout, '{codFeeCents}', s.before->'codFeeCents') FROM public.store_currency_snapshots s WHERE s.change_id = p_change AND s.table_name = 'store_settings' AND t.creator_id = s.row_id; UPDATE public.store_settings SET currency = v_change.previous_currency, updated_at = now() WHERE creator_id = p_creator; UPDATE public.store_currency_changes SET restored_at = now() WHERE id = p_change; RETURN jsonb_build_object('ok', true, 'repeat', false, 'currency', v_change.from_currency, 'counts', v_counts); END $fn$;
REVOKE ALL ON FUNCTION public.store_currency_targets() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.store_change_currency(uuid, text, text, text, numeric, date, text, uuid) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.store_currency_restore(uuid, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.store_currency_targets() TO service_role;
GRANT EXECUTE ON FUNCTION public.store_change_currency(uuid, text, text, text, numeric, date, text, uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.store_currency_restore(uuid, uuid) TO service_role;
notify pgrst, 'reload schema';
